question.answer:
package main

func page(ledger []int, from, to int) []int {
	return ledger[from:to]
}

func redact(entries []int) {
	for i := range entries {
		entries[i] = 0
	}
}

func trim(ledger []int) []int {
	return ledger[:len(ledger)-1]
}

testcode.text:
entries := []int{7, 8, 9}
redact(entries)
fmt.Println(entries, trim([]int{4, 5, 6}))

