question.answer:
package main

func snapshot(board []string) []string {
	out := make([]string, len(board))
	copy(out, board)
	return out
}

func record(pad []string, msgs []string) int {
	return copy(pad, msgs)
}

func pin(board []string, msg string) {
	copy(board[1:], board)
	board[0] = msg
}

testcode.text:
pad := []string{"-", "-", "-"}
n := record(pad, []string{"alpha", "bravo"})
fmt.Println(n, pad)
board := []string{"alpha", "bravo"}
pin(board, "charlie")
fmt.Println(board)

