// discount lowers every price on the board by pct percent, in place.
func discount(prices []int, pct int) {
	for i := 0; i < len(prices); i++ {
		prices[i] = prices[i] * (100 - pct) / 100
	}
}

// cheapest returns the index of the lowest price, or -1 for an empty board.
func cheapest(prices []int) int {
	if len(prices) == 0 {
		return -1
	}
	best := 0
	for i := 1; i < len(prices); i++ {
		if prices[i] < prices[best] {
			best = i
		}
	}
	return best
}

// total returns the sum of every price on the board.
func total(prices []int) int {
	sum := 0
	for i := 0; i < len(prices); i++ {
		sum = sum + prices[i]
	}
	return sum
}

question.answer:
package main

// discount lowers every price on the board by pct percent, in place.
func discount(prices []int, pct int) {
	for i, p := range prices {
		prices[i] = p * (100 - pct) / 100
	}
}

// cheapest returns the index of the lowest price, or -1 for an empty board.
func cheapest(prices []int) int {
	if len(prices) == 0 {
		return -1
	}
	best := 0
	for i, p := range prices {
		if p < prices[best] {
			best = i
		}
	}
	return best
}

// total returns the sum of every price on the board.
func total(prices []int) int {
	sum := 0
	for _, p := range prices {
		sum += p
	}
	return sum
}

testcode.text:
board := []int{40, 25, 60}
discount(board, 10)
fmt.Println(board, total(board))
